99	            members.put(rs.getString(1), new ArrayList<>());
100	            totals.put(rs.getString(1), BigDecimal.ZERO.setScale(2));
101	        }, sheetId);
102	        Map<String, String> parents = new HashMap<>();
103	        jdbc.query("SELECT m.pool, m.person_id, COALESCE(p.name, m.member_pool), m.share, p.retired_from IS NOT NULL, "
104	                + "m.member_pool, m.from_date, m.to_date, "
105	                + "(m.from_date IS NULL OR s.today IS NULL OR m.from_date <= s.today) "
106	                + "AND (m.to_date IS NULL OR s.today IS NULL OR m.to_date >= s.today) "
107	                + "FROM pool_member m LEFT JOIN person p ON p.id = m.person_id "
108	                + "LEFT JOIN sheet s ON s.id = m.sheet_id "
109	                + "WHERE m.sheet_id = ? ORDER BY m.position", rs -> {
110	                    String pool = rs.getString(1);
111	                    List<PoolMemberResponse> list = members.get(pool);
