127	        // The people with a hold in force on the sheet's today: they get no cut.
128	        Set<Long> held = new HashSet<>(jdbc.query("SELECT DISTINCT h.person_id FROM person_hold h "
129	                + "JOIN sheet s ON s.id = h.sheet_id WHERE h.sheet_id = ? AND h.from_date <= s.today "
130	                + "AND (h.to_date IS NULL OR h.to_date >= s.today)", (rs, i) -> rs.getLong(1), sheetId));
131	        Map<String, List<PoolMemberResponse>> shown = new LinkedHashMap<>();
132	        for (String name : members.keySet()) {
