134	        }
135	        List<PoolResponse> pools = new ArrayList<>();
136	        members.forEach((name, list) -> {
137	            BigDecimal total = totals.get(name);
138	            boolean balanced = total.compareTo(FULL) == 0;
139	            pools.add(new PoolResponse(name, shown.getOrDefault(name, list), total.toPlainString(), balanced));
140	        });
