144	    /** Shares the pool's pot (null for none) among its members, then each member pool's cut among its own. */
145	    private static void share(String name, BigDecimal pot, Map<String, List<PoolMemberResponse>> members,
146	            Map<String, BigDecimal> totals, Set<Long> held, Map<String, List<PoolMemberResponse>> shown, int depth) {
147	        if (shown.containsKey(name) || depth > MAX_DEPTH) return;
148	        List<PoolMemberResponse> list = members.get(name);
149	        boolean balanced = totals.get(name).compareTo(FULL) == 0;
150	        List<PoolMemberResponse> withCuts = balanced && pot != null ? cuts(list, pot, held) : list;
151	        shown.put(name, withCuts);
152	        for (PoolMemberResponse m : withCuts) {
153	            if (m.pool() != null && members.containsKey(m.pool())) {
154	                share(m.pool(), m.cut() == null ? null : new BigDecimal(m.cut()), members, totals, held, shown, depth + 1);
155	            }
156	        }
157	    }
158	
159	    /** The members with their cuts of the pot. A retired member is left out of the cuts and a person
160	     *  with a hold in force on the sheet's today has none: each shows 0.00, their share spread over the
161	     *  others in proportion to those others' shares. When every member in their dates is retired, no
162	     *  member has a cut at all (null); each other member's is the pot times their share divided by
163	     *  the shares of the members with a cut added up, rounded half to even to two decimals. The
164	     *  remainder, the pot less the cuts, goes to the member with the smallest non-zero cut, the latest
165	     *  added on a tie (the last member with a cut when every cut is 0.00), so the cuts total the pot
166	     *  (when no member has a cut, each is 0.00). A member out of their dates is left out: no cut at all (null). */
167	    private static List<PoolMemberResponse> cuts(List<PoolMemberResponse> members, BigDecimal pot, Set<Long> held) {
168	        boolean allRetired = members.stream().anyMatch(PoolMemberResponse::current)
169	                && members.stream().filter(PoolMemberResponse::current).allMatch(PoolMemberResponse::retired);
170	        if (allRetired) {
171	            List<PoolMemberResponse> none = new ArrayList<>(members.size());
172	            for (PoolMemberResponse m : members) {
173	                none.add(new PoolMemberResponse(m.personId(), m.name(), m.share(), m.retired(), null, m.pool(),
174	                        m.from(), m.to(), m.current()));
175	            }
176	            return none;
177	        }
178	        BigDecimal[] cuts = new BigDecimal[members.size()];
179	        boolean[] cut = new boolean[members.size()];
180	        BigDecimal shares = BigDecimal.ZERO;
181	        for (int i = 0; i < members.size(); i++) {
182	            PoolMemberResponse m = members.get(i);
183	            cut[i] = m.current() && !m.retired() && (m.personId() == null || !held.contains(m.personId()));
184	            if (cut[i]) shares = shares.add(new BigDecimal(m.share()));
185	        }
186	        BigDecimal sum = BigDecimal.ZERO.setScale(2);
187	        int smallest = -1;
188	        int last = -1;
189	        for (int i = 0; i < members.size(); i++) {
190	            PoolMemberResponse m = members.get(i);
191	            BigDecimal share = new BigDecimal(m.share());
192	            cuts[i] = !cut[i] || shares.signum() == 0 ? BigDecimal.ZERO.setScale(2)
193	                    : pot.multiply(share).divide(shares, 2, RoundingMode.HALF_EVEN);
194	            sum = sum.add(cuts[i]);
195	            if (cut[i] && shares.signum() != 0) {
196	                last = i;
197	                if (cuts[i].signum() != 0 && (smallest < 0 || cuts[i].compareTo(cuts[smallest]) <= 0)) smallest = i;
198	            }
199	        }
200	        int to = smallest >= 0 ? smallest : last;
201	        if (to >= 0) cuts[to] = cuts[to].add(pot.subtract(sum));
202	        List<PoolMemberResponse> withCuts = new ArrayList<>(members.size());
203	        for (int i = 0; i < members.size(); i++) {
204	            PoolMemberResponse m = members.get(i);
205	            withCuts.add(new PoolMemberResponse(m.personId(), m.name(), m.share(), m.retired(),
206	                    m.current() ? cuts[i].toPlainString() : null, m.pool(), m.from(), m.to(), m.current()));
207	        }
208	        return withCuts;
209	    }
