386	            name = request.personId() == null ? null : pools.personName(sheetId, request.personId());
387	            if (name == null) {
388	                throw new InvalidSheetRequestException("No such person");
389	            }
390	        }
391	        String text = request.share() == null ? "" : request.share().trim();
392	        if (!SHARE.matcher(text).matches()) {
393	            throw new InvalidSheetRequestException("A share is a percent with up to two decimals");
394	        }
395	        BigDecimal share = new BigDecimal(text).setScale(2);
396	        if (share.signum() <= 0 || share.compareTo(MAX) > 0) {
397	            throw new InvalidSheetRequestException("A share is more than 0.00 and at most 100.00");
398	        }
399	        LocalDate from = date(request.from());
400	        LocalDate to = date(request.to());
401	        if (from != null && to != null && to.isBefore(from)) {
402	            throw new InvalidSheetRequestException("A to-date cannot be before the from-date");
403	        }
404	        if (memberPool != null) {
405	            validatePool(sheetId, request.pool(), memberPool, pools);
406	            member.set(new PoolMember(sheetId, request.pool(), null, memberPool, name, share, request.user(), from, to));
407	            return;
408	        }
409	        if (pools.hasMember(sheetId, request.pool(), request.personId())) {
410	            throw new InvalidSheetRequestException(name + " is already in " + request.pool());
411	        }
412	        member.set(new PoolMember(sheetId, request.pool(), request.personId(), null, name, share, request.user(), from, to));
413	    }
414	
415	    /** The date (yyyy-mm-dd), or null when blank. */
416	    private static LocalDate date(String raw) throws InvalidSheetRequestException {
417	        if (raw == null || raw.isBlank()) return null;
418	        try {
419	            return LocalDate.parse(raw.trim());
420	        } catch (DateTimeParseException e) {
421	            throw new InvalidSheetRequestException("Not a date (yyyy-mm-dd): " + raw);
422	        }
423	    }
424	
425	    /** Refuses a pool already a member of a pool, one that would contain itself through any chain, and
426	     *  one that would make a chain of pools more than {@link Pools#MAX_DEPTH} deep. */
427	    private static void validatePool(String sheetId, String pool, String memberPool, Pools pools)
428	            throws InvalidSheetRequestException {
429	        if (pools.parentOf(sheetId, memberPool) != null) {
430	            throw new InvalidSheetRequestException(memberPool + " is already a member of a pool");
431	        }
432	        // The pools above, the pool itself among them.
433	        int above = 0;
434	        for (String p = pool; p != null && above <= Pools.MAX_DEPTH; p = pools.parentOf(sheetId, p)) {
435	            if (p.equals(memberPool)) {
436	                throw new InvalidSheetRequestException(memberPool + " cannot contain itself");
437	            }
438	            above++;
439	        }
440	        if (above + height(sheetId, memberPool, pools, 0) > Pools.MAX_DEPTH) {
441	            throw new InvalidSheetRequestException("A chain of pools is at most " + Pools.MAX_DEPTH + " deep");
442	        }
443	    }
444	
445	    /** How many pools deep the chain below the pool runs, the pool itself counted. */
446	    private static int height(String sheetId, String pool, Pools pools, int depth) {
447	        if (depth > Pools.MAX_DEPTH) return depth;
448	        int most = 0;
449	        for (String m : pools.memberPools(sheetId, pool)) most = Math.max(most, height(sheetId, m, pools, depth + 1));
450	        return 1 + most;
451	    }
452	}
